struct Closer{source:core::OriginalSourceTurnIdentity,calls:std::sync::Arc<std::sync::atomic::AtomicUsize>,interrupt:bool}
impl OriginalEffectProducer for Closer{
 type Output=RetainedCloneStep;type Failure=OriginalRetirementFailure;type Context<'a,'b>=(&'a core::OriginalSourceTurn,&'a mut Option<ControlledRetirement<NativeEncodeProducerFailure>>) where 'b:'a;
 fn validate_context<'a,'b>(&self,c:&Self::Context<'a,'b>)->Result<(),ValueError>where 'b:'a{if c.0.identity()==self.source{Ok(())}else{Err(ValueError::invariant("foreign original retirement Source"))}}
 fn source_turn<'a,'b>(&self,c:&Self::Context<'a,'b>)->Option<core::OriginalSourceTurnIdentity>where 'b:'a{Some(c.0.identity())}
 fn receive<'r,'a,'b>(&mut self,c:&mut Self::Context<'a,'b>,effect:&mut core::RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,RetainedCloneStep,OriginalRetirementFailure>)->Result<OriginalEffectReplyComplete<'r,RetainedCloneStep,OriginalRetirementFailure>,ValueError>where 'b:'a{self.calls.fetch_add(1,std::sync::atomic::Ordering::SeqCst);let answer=c.1.as_mut().ok_or_else(||ValueError::invariant("original retirement cursor absent"))?.step_into(effect,reply)?;if self.interrupt&&answer.is_recorded(){self.interrupt=false;drop(answer);panic!("actual child retirement replied before unwind")}Ok(answer)}
 fn recover<'r,'a,'b>(&mut self,c:&mut Self::Context<'a,'b>,effect:&mut core::RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,RetainedCloneStep,OriginalRetirementFailure>)->Result<OriginalEffectReplyComplete<'r,RetainedCloneStep,OriginalRetirementFailure>,ValueError>where 'b:'a{c.1.as_mut().ok_or_else(||ValueError::invariant("original retirement cursor absent"))?.recover_step_into(effect,reply)}
}
pub(super) fn retire(turn:&core::OriginalSourceTurn,work:&mut core::OriginalWork<'_>,physical:&mut core::OriginalConstructionLoan<'_>,source:&mut Option<Result<NativeEncodeProducerOutcome,NativeEncodeProducerFailure>>){
 let calls=std::sync::Arc::new(std::sync::atomic::AtomicUsize::new(0));let mut interrupted=false;let mut cursor=None;let mut owner=Some(OriginalEffectAuthority::new(Closer{source:turn.identity(),calls:calls.clone(),interrupt:true}));let mut action=None;let mut status=None;let demand=RetirementDemand{copy_bytes:std::mem::size_of_val(source)+std::mem::size_of::<Option<ControlledRetirement<NativeEncodeProducerFailure>>>(),depth:1,..Default::default()};let mut birth=Payment::default();birth.begin(work,physical,demand);birth.stage(work,physical,|_,_,effect|{assert!(effect.performed(1).unwrap());let Err(failure)=source.take().expect("actual child reply retained") else{panic!("actual producer reply changed")};cursor=Some(ControlledRetirement::retain(failure));core::RetainedWorkOutcome{result:Ok(Some(RetainedCloneProgress{copied_items:1,copied_bytes:demand.copy_bytes,..Default::default()})),work:1}});assert!(birth.settle(work,physical));birth.finish(work,physical);
 for _ in 0..128{let control=cursor.as_ref().unwrap();if control.terminal_is_empty(){break}assert!(!control.requires_original_birth(),"the selected original failure requires its actual recipient birth");let demand=control.next_demand(4096).unwrap();let units=control.next_computational_work(4096).unwrap();let mut step=Payment::default();step.begin_units(work,physical,demand,units);let mut run=||step.stage(work,physical,|_,_,effect|{let before=effect.performed_work();let mut context=(turn,&mut cursor);let ready=owner.as_mut().unwrap().drive(&mut context,effect,&mut action).unwrap();assert!(ready,"original child retirement remains pending");let progress=action.as_ref().unwrap().recorded_reply().unwrap().as_ref().unwrap().progress();let actual=effect.performed_work().checked_sub(before).expect("original performed work is monotonic");core::RetainedWorkOutcome{result:Ok(Some(progress)),work:actual}});if interrupted{run()}else{let stopped=std::panic::catch_unwind(std::panic::AssertUnwindSafe(&mut run));assert!(stopped.is_err());let before=calls.load(std::sync::atomic::Ordering::SeqCst);run();assert_eq!(calls.load(std::sync::atomic::Ordering::SeqCst),before);interrupted=true}drop(run);assert!(step.settle(work,physical));step.finish(work,physical);let mut transfer=Payment::default();transfer.begin(work,physical,OriginalEffectAuthority::<Closer>::copy_success_demand().unwrap());transfer.stage(work,physical,|_,_,effect|{let context=(turn,&mut cursor);owner.as_ref().unwrap().replace_copy_success_into(&context,action.as_mut().unwrap(),&mut status,effect)});assert!(transfer.settle(work,physical));transfer.finish(work,physical);owner.as_mut().unwrap().finish(&mut action).unwrap();assert!(status.is_some())}
 assert!(interrupted);assert!(cursor.as_ref().unwrap().terminal_is_empty(),"original child retirement did not finish");let demand=RetirementDemand{copy_bytes:std::mem::size_of_val(&status),depth:1,..Default::default()};let mut release=Payment::default();release.begin(work,physical,demand);release.stage(work,physical,|_,_,effect|{assert!(effect.performed(1).unwrap());status=None;core::RetainedWorkOutcome{result:Ok(Some(RetainedCloneProgress{copied_items:1,copied_bytes:demand.copy_bytes,..Default::default()})),work:1}});assert!(release.settle(work,physical));release.finish(work,physical);let demand=RetirementDemand{copy_bytes:std::mem::size_of_val(&cursor),depth:1,..Default::default()};let mut release=Payment::default();release.begin(work,physical,demand);release.stage(work,physical,|_,_,effect|{assert!(semio_framework_value_retirement::ErasedSnapshotRetirement::native_header_release(cursor.as_ref().unwrap()).is_some());assert!(effect.performed(1).unwrap());drop(cursor.take());core::RetainedWorkOutcome{result:Ok(Some(RetainedCloneProgress{copied_items:1,copied_bytes:demand.copy_bytes,..Default::default()})),work:1}});assert!(release.settle(work,physical));release.finish(work,physical);let mut returned=None;let mut transfer=Payment::default();transfer.begin(work,physical,OriginalEffectAuthority::<Closer>::producer_transfer_demand().unwrap());transfer.stage(work,physical,|_,_,effect|{let context=(turn,&mut cursor);OriginalEffectAuthority::transfer_producer(&mut owner,&context,&mut returned,effect)});assert!(transfer.settle(work,physical));transfer.finish(work,physical);let demand=RetirementDemand{copy_bytes:std::mem::size_of_val(&returned),depth:1,..Default::default()};let mut release=Payment::default();release.begin(work,physical,demand);release.stage(work,physical,|_,_,effect|{assert!(effect.performed(1).unwrap());drop(returned.take());core::RetainedWorkOutcome{result:Ok(Some(RetainedCloneProgress{copied_items:1,copied_bytes:demand.copy_bytes,..Default::default()})),work:1}});assert!(release.settle(work,physical));release.finish(work,physical);assert!(source.is_none()&&owner.is_none()&&action.is_none())
}
